    $json${"additionalProperties":false,"properties":{"contacto":{"description":"WhatsApp, dirección o redes, solo si la persona los dio","title":"Contacto","type":"string"},"foto_producto":{"contentEncoding":"base64","contentMediaType":"image/jpeg","description":"Opcional: se le quita el fondo","title":"Foto del producto","type":"string"},"llamada_accion":{"description":"Por ejemplo: Ven hoy, Pide por WhatsApp","title":"Llamada a la acción","type":"string"},"logo":{"contentEncoding":"base64","contentMediaType":"image/png","description":"Opcional: se le quita el fondo y se toman sus colores","title":"Logo","type":"string"},"mensaje":{"description":"Una frase de apoyo; puede venir de la IA","title":"Mensaje","type":"string"},"negocio":{"description":"Nombre del negocio, por ejemplo Frío Rico","title":"Negocio","type":"string"},"oferta":{"description":"Lo que va en grande: 2x1 en conos, -20 %, $9.900","title":"Oferta","type":"string"},"titular":{"description":"Frase principal corta, máximo 6 palabras","title":"Titular","type":"string"}},"required":["negocio","oferta"],"type":"object"}$json$::jsonb,
    $json${"additionalProperties":false,"properties":{"poster":{"contentEncoding":"base64","contentMediaType":"image/jpeg","title":"Póster","type":"string"},"poster_alternativo":{"contentEncoding":"base64","contentMediaType":"image/jpeg","title":"Póster (otra versión)","type":"string"},"resumen":{"title":"Resumen","type":"string"}},"required":["poster","poster_alternativo","resumen"],"type":"object"}$json$::jsonb,
    $json${"connector":{"hosts":[],"key":"poster_promocional@1","provider":"Capacita (diseño local)","provider_url":"https://capacita.local/diseno","seal":"conectada"},"definition":{"constraints":["Las imágenes se procesan en Capacita y no se envían a ningún servicio.","Usa solo los textos que dio la persona: no inventa precios, teléfonos ni direcciones."],"definition_hash":"2d514c5764b0d6d71351d74d375b7627d8f0b8ba7390f63a69a8902a41ab5c4f","examples":[{"inputs":{"llamada_accion":"Ven hoy","negocio":"Frío Rico","oferta":"2x1 en conos","titular":"Refréscate al doble"},"parameters":{"estilo":"automatico","formato":"cuadrado"}}],"failure_cases":[],"format_version":1,"parameter_schema":{"additionalProperties":false,"properties":{"estilo":{"default":"automatico","description":"automatico toma los colores del logo o del tipo de negocio","enum":["automatico","fresco","vibrante","elegante","natural","calido"],"title":"Estilo","type":"string"},"formato":{"default":"cuadrado","description":"cuadrado 1080×1080 (publicación) o historia 1080×1920 (estados e historias)","enum":["cuadrado","historia"],"title":"Formato","type":"string"}},"required":["formato","estilo"],"type":"object"},"required_permissions":[],"resources":[]}}$json$::jsonb)
