","pais"],"type":"object"},"required_permissions":[],"resources":[]},"definition_hash":"8b718f01cf80d78965dfb570376db577ae3fafe2a7f7e629609b2b7f57f5066c","format_version":1,"hosts":["api.open-meteo.com","geocoding-api.open-meteo.com"],"kind":"connector","provider":"Open-Meteo","provider_url":"https://open-meteo.com"}$json$::jsonb,
