erties":{"pais":{"default":"CO","description":"Código de 2 letras del país donde buscar la ciudad (CO = Colombia)","maxLength":2,"minLength":2,"title":"País","type":"string"}},"required":["pais"],"type":"object"},"required_permissions":[],"resources":[]},"definition_hash":"ddf61105d85946b31540c475ebeabdb4d6ac38bd22b147b06039872e26e42265","format_version":1,"hosts":["archive-api.open-meteo.com","geocoding-api.open-meteo.com"],"kind":"connector","provider":"Open-Meteo","provider_url":"https://open-meteo.com"}$json$::jsonb,
